import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic 2D benchmark function combining a modified Schwefel function, interaction terms, and a sigmoid skew.

    The function combines a modified version of Schwell function with interaction terms and a skewed sigmoid.

    Formula:
    f(x) =  sum(abs(x)) + prod(tanh(x)) . + sigmoid(x[0]) + gaussian_bump(x)
    """
    x = x * 2 # rescale coordinates from [-5, 5] to [-10, 10]

    def sigmoid(z):
        return 1 / (1 + np.exp(-z))

    def gaussian_bump(z):
        center = np.array([1.0, -0.5])
        width = 0.5
        amplitude = 0.5
        return amplitude * np.exp(-np.sum((z - center)**2) / (2 * width**2))

    return np.sum(np.abs(x)) + np.prod(np.tanh(x)) + sigmoid(x[0]) + gaussian_bump(x)
